import type { AgentPersistedMessageContentPart } from './agents';
export interface ToolSuspendedPayload {
    toolCallId: string;
    runId: string;
    toolName: string;
    input: unknown;
}
export interface AgentSseMessage {
    role: string;
    content: AgentPersistedMessageContentPart[];
}
export type ForwardedChildChunkWire = {
    type: 'text-delta';
    id: string;
    delta: string;
} | {
    type: 'reasoning-start';
    id: string;
} | {
    type: 'reasoning-delta';
    id: string;
    delta: string;
} | {
    type: 'reasoning-end';
    id: string;
} | {
    type: 'tool-input-start';
    toolCallId: string;
    toolName: string;
} | {
    type: 'tool-execution-start';
    toolCallId: string;
    toolName: string;
    startTime: number;
} | {
    type: 'tool-execution-end';
    toolCallId: string;
    toolName: string;
    isError: boolean;
    endTime: number;
};
export type AgentSseEvent = {
    type: 'start-step';
} | {
    type: 'finish-step';
} | {
    type: 'text-start';
    id: string;
} | {
    type: 'text-delta';
    id: string;
    delta: string;
} | {
    type: 'text-end';
    id: string;
} | {
    type: 'reasoning-start';
    id: string;
} | {
    type: 'reasoning-delta';
    id: string;
    delta: string;
} | {
    type: 'reasoning-end';
    id: string;
} | {
    type: 'tool-input-start';
    toolCallId: string;
    toolName: string;
} | {
    type: 'tool-input-delta';
    toolCallId: string;
    delta: string;
} | {
    type: 'tool-call';
    toolCallId: string;
    toolName: string;
    input: unknown;
} | {
    type: 'tool-execution-start';
    toolCallId: string;
    toolName: string;
    startTime: number;
} | {
    type: 'tool-execution-end';
    toolCallId: string;
    toolName: string;
    isError: boolean;
    endTime: number;
} | {
    type: 'tool-result';
    toolCallId: string;
    toolName: string;
    output: unknown;
    isError?: boolean;
    canceled?: boolean;
} | {
    type: 'tool-call-suspended';
    payload: ToolSuspendedPayload;
} | {
    type: 'subagent-chunk';
    parentToolCallId: string;
    taskPath: string;
    chunk: ForwardedChildChunkWire;
} | {
    type: 'message';
    message: AgentSseMessage;
} | {
    type: 'warning';
    message: string;
    code?: string;
    source?: 'mcp';
    server?: string;
} | {
    type: 'error';
    message: string;
    errorCode?: string;
    missing?: string[];
} | {
    type: 'done';
    sessionId?: string;
    executionId?: string;
};
